def extract_fields(record: dict, paths: dict[str, str], default=None, required: set | None = None) -> dict:
    """
    Extract fields from a nested record using dot-separated paths.

    Args:
        record: The source dictionary to extract values from.
        paths: A mapping of output_key -> dot-separated path string.
        default: Value to use when a path cannot be resolved.
        required: A set of output keys that must be resolved; if a required key
                  cannot be resolved, KeyError is raised instead of using default.

    Returns:
        A dictionary mapping each output key to the extracted (or default) value.

    Raises:
        TypeError: If record is not a dict, paths is not a dict, or required is
                   not a set/frozenset/None.
        ValueError: If any key in paths is not a string, or any path value is
                    not a non-empty string.
        KeyError: If an output key is in required and its path cannot be resolved.
    """
    if not isinstance(record, dict):
        raise TypeError(
            f"record must be a dict, got {type(record).__name__!r}"
        )
    if not isinstance(paths, dict):
        raise TypeError(
            f"paths must be a dict, got {type(paths).__name__!r}"
        )
    if required is not None and not isinstance(required, (set, frozenset)):
        raise TypeError(
            f"required must be a set or frozenset or None, got {type(required).__name__!r}"
        )

    for output_key, path in paths.items():
        if not isinstance(output_key, str):
            raise ValueError(
                f"All keys in paths must be strings, got {type(output_key).__name__!r}"
            )
        if not isinstance(path, str):
            raise ValueError(
                f"All path values in paths must be strings, got {type(path).__name__!r} "
                f"for key {output_key!r}"
            )
        if not path:
            raise ValueError(
                f"Path for key {output_key!r} must be a non-empty string"
            )

    result = {}

    for output_key, path in paths.items():
        parts = path.split(".")
        resolved, value = _resolve_path(record, parts)

        if not resolved:
            if required is not None and output_key in required:
                raise KeyError(output_key)
            result[output_key] = default
        else:
            result[output_key] = value

    return result

